for (const item of $input.all()) {
  item.json.id = item.json.output.id + ''
  item.json.message = item.json.output.message
  delete item.json.output
}

return $input.all();

const json = $input.item.json;

$input.item.json = {
  message: json.message?.text ?? json.content ?? json.text
}

return $input.item;

